package main

// Plugin-local derivation of a serial-record document's display title and
// season from the raw directory facts the scanner stamps (dir_name_raw, with
// series_relative_path as the fallback). The enrich chain hands every source a
// base built from doc["parsed"] alone and never writes a derived title back
// into parsed, so the shikimori Match derives its search title itself from
// exactly the fields the document carries — mirroring the derivation
// plugins/serial-parser applies to the same fields (parseSeriesDir over the
// shared releasename grammar), in plugin-local form: this plugin imports only
// pkg/sdk + proto + stdlib.
//
// The mirror covers the directory-name passes that shape a search query —
// video-extension strip, the two-part bracket rule, the anchored season
// markers (Nth Season / Season N / standalone Sxx / TV N), the trailing roman
// sequel (II-IX), the trailing group tag, and separator cleaning — with
// serial-parser's adapter rule that the season is ALWAYS >= 1 (the marker's
// value, else 1). The full release-tag vocabulary stays serial-parser's: a
// directory name carrying bare release tokens ("Show 1080p") keeps them in
// the derived title, where the upstream search tolerates them.

import (
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

// deriveSeriesName parses a raw serial directory name (or a file-backed
// serial's raw file name) into the display title and the query season — the
// shape of serial-parser's parseSeriesDir adapter. Pure. The season is always
// >= 1: the explicit marker's value when a marker is present, 1 otherwise.
func deriveSeriesName(raw string) (title string, season int64) {
	name := stripVideoExt(raw)
	stripped := stripBracketSegments(name)
	if rest, n, ok := cutSeasonMarker(stripped); ok {
		stripped, season = rest, int64(n)
	} else if m := romanSequelRe.FindStringSubmatchIndex(stripped); m != nil {
		season = int64(romanSeasons[strings.ToLower(stripped[m[2]:m[3]])])
		stripped = stripped[:m[0]]
	}
	stripped = cutTrailingGroupTag(stripped)
	title = cleanSeriesTitle(stripped)
	if title == "" {
		title = cleanSeriesTitle(name) // a name that was ONLY tokens still yields its cleaned form
	}
	if season < 1 {
		season = 1 // the adapter owns the default; an unmarked record is season 1
	}
	return title, season
}

// Grammar tables — plugin-local copies of the shared grammar's directory-name
// regexes (Unicode-first-class: a Cyrillic directory name parses correctly;
// the season tokens are ASCII and the title is whatever surrounds them).

var (
	// bracketSegmentRe matches one [...] or (...) segment.
	bracketSegmentRe = regexp.MustCompile(`\[[^\]]*\]|\([^)]*\)`)
	// crcHexRe matches a CRC-like 8-hex-digit token ([C48E56C8]).
	crcHexRe = regexp.MustCompile(`(?i)^[0-9a-f]{8}$`)
	// yearRe matches a bare release year.
	yearRe = regexp.MustCompile(`^(?:19|20)\d{2}$`)
	// pureNumberRe matches a 1-3 digit pure number ([01]).
	pureNumberRe = regexp.MustCompile(`^\d{1,3}$`)
	// resolutionShapeRe matches a resolution token ([1080p], [720i]).
	resolutionShapeRe = regexp.MustCompile(`(?i)^\d{3,4}[pi]$`)
	// subsRe matches a subtitle-combinator token (Multi5-Subs, SUBS).
	subsRe = regexp.MustCompile(`(?i)^(?:multi\d*-?)?subs$`)
	// allCapsRe matches an all-caps acronym of <= 5 letters ([ADN], [KTX]).
	allCapsRe = regexp.MustCompile(`^[A-Z0-9]{2,5}$`)
	// nthSeasonRe matches the "4th Season" directory-marker form.
	nthSeasonRe = regexp.MustCompile(`(?i)(\d{1,2})(?:st|nd|rd|th)[\s._-]*season`)
	// seasonWordRe matches the "Season 2" word-form marker, beside the
	// "4th Season" ordinal form.
	seasonWordRe = regexp.MustCompile(`(?i)(?:^|[\s._\-\[(])season[\s._-]*(\d{1,2})(?:$|[\s._\-\])])`)
	// seasonTokenRe finds a standalone Sxx season marker, preceded by
	// start-of-string or a separator. A following episode digit or 'e'
	// disqualifies the match (that is an SxxExx token) — checked in code,
	// since Go's regexp has no lookahead.
	seasonTokenRe = regexp.MustCompile(`(?i)(?:^|[\s._\-\[(])s(\d{1,3})`)
	// tvSeasonRe matches a whole-token "TV <N>" season marker.
	tvSeasonRe = regexp.MustCompile(`(?i)(?:^|[\s._\-\[(])tv[\s._-]*(\d{1,2})(?:$|[\s._\-\])])`)
	// romanSequelRe matches a trailing whole-token roman sequel suffix, II-IX
	// only — single-letter romans (I, V, X) are excluded.
	romanSequelRe = regexp.MustCompile(`(?i)(?:^|[\s._\-\[(])(II|III|IV|VI|VII|VIII|IX)[\s._\-\])]*$`)
	// trailingGroupTagRe captures a trailing single word after a separator
	// (" - FanGroup"); the word must clear the group-tag shape rule first.
	trailingGroupTagRe = regexp.MustCompile(`[\s._\-]*([A-Za-z][A-Za-z0-9]*)[\s._\-]*$`)
)

// romanSeasons maps the accepted sequel suffixes (lowercased) to their season
// values. Range II-IX.
var romanSeasons = map[string]int{
	"ii": 2, "iii": 3, "iv": 4, "vi": 6, "vii": 7, "viii": 8, "ix": 9,
}

// videoExtensions is the trailing-extension set a file-backed serial name may
// carry; directory names carry none and pass through unchanged.
var videoExtensions = map[string]bool{
	".mkv": true, ".mp4": true, ".m4v": true, ".mov": true, ".avi": true,
	".webm": true, ".wmv": true, ".flv": true, ".mpg": true, ".mpeg": true,
	".ts": true, ".m2ts": true,
}

// stripVideoExt drops a trailing video extension from a file-backed serial
// name; directory names carry no video extension and pass through unchanged.
func stripVideoExt(name string) string {
	ext := filepath.Ext(name)
	if !videoExtensions[strings.ToLower(ext)] {
		return name
	}
	return strings.TrimSuffix(name, ext)
}

// stripBracketSegments applies the two-part bracket rule: a bracket/paren
// segment at the name's start is group-tag position and strips regardless of
// its inner shape; a segment elsewhere strips only when its content matches a
// release mask; a non-leading segment matching no mask is PRESERVED — its
// title text keeps, e.g. "Title_(Shiro)".
func stripBracketSegments(name string) string {
	type span struct{ start, end int }
	var spans []span
	for _, m := range bracketSegmentRe.FindAllStringSubmatchIndex(name, -1) {
		inner := strings.TrimSpace(name[m[0]+1 : m[1]-1])
		if strings.TrimSpace(name[:m[0]]) != "" && !segmentIsReleaseDecoration(inner) {
			continue // non-leading, no mask match — preserve the segment
		}
		spans = append(spans, span{m[0], m[1]})
	}
	if len(spans) == 0 {
		return name
	}
	var b strings.Builder
	last := 0
	for _, s := range spans {
		b.WriteString(name[last:s.start])
		b.WriteString(" ")
		last = s.end
	}
	b.WriteString(name[last:])
	return b.String()
}

// segmentIsReleaseDecoration reports whether a bracket segment's inner text
// matches a release mask: a year, a pure 1-3 digit number, a resolution shape,
// CRC-like hex, a subs/dub combinator, an all-caps acronym of <= 5 letters, or
// a group-tag-shape segment containing any of those.
func segmentIsReleaseDecoration(inner string) bool {
	if yearRe.MatchString(inner) || pureNumberRe.MatchString(inner) ||
		resolutionShapeRe.MatchString(inner) || crcHexRe.MatchString(inner) ||
		subsRe.MatchString(inner) || allCapsRe.MatchString(inner) ||
		isGroupTagShape(inner) {
		return true
	}
	tokens := strings.FieldsFunc(inner, func(r rune) bool {
		return r == ' ' || r == '.' || r == '_' || r == '-' || r == '+' || r == '/'
	})
	for _, tok := range tokens {
		if subsRe.MatchString(tok) || isGroupTagShape(tok) {
			return true
		}
	}
	return false
}

// isGroupTagShape reports whether a single word is a release-group tag shape:
// >= 3 ASCII letters with mixed case AND an interior capital after a
// lowercase ("FanGroup"). An ordinary capitalized word ("Remastered",
// "Arc") has no interior capital and never matches.
func isGroupTagShape(word string) bool {
	if len(word) < 3 {
		return false
	}
	hasLower, hasInteriorUpper := false, false
	for i := 0; i < len(word); i++ {
		c := word[i]
		switch {
		case c >= 'a' && c <= 'z':
			hasLower = true
		case c >= 'A' && c <= 'Z':
			if i > 0 {
				hasInteriorUpper = true
			}
		default:
			return false // a non-ASCII-letter byte: not a single CamelCase word
		}
	}
	return hasLower && hasInteriorUpper
}

// cutSeasonMarker finds the first anchored season marker in a name and returns
// the name with that marker's span replaced by a space, its number, and true.
// Priority: Nth Season, Season N, standalone Sxx, TV <N>. Anchored forms only
// — an internal digit ("Title_3_The_End") or a trailing bare digit ("Title 0")
// is never a marker.
func cutSeasonMarker(name string) (rest string, n int, ok bool) {
	for _, re := range []*regexp.Regexp{nthSeasonRe, seasonWordRe} {
		if m := re.FindStringSubmatchIndex(name); m != nil {
			return spliceCut(name, m[0], m[1]), seriesAtoi(name[m[2]:m[3]]), true
		}
	}
	if m := seasonTokenIndex(name); m != nil {
		return spliceCut(name, m[0], m[1]), seriesAtoi(name[m[2]:m[3]]), true
	}
	if m := tvSeasonRe.FindStringSubmatchIndex(name); m != nil {
		return spliceCut(name, m[0], m[1]), seriesAtoi(name[m[2]:m[3]]), true
	}
	return name, 0, false
}

// spliceCut replaces name[start:end] with a single space.
func spliceCut(name string, start, end int) string {
	return name[:start] + " " + name[end:]
}

// seasonTokenIndex returns the match indices of the first standalone Sxx
// marker, or nil. An Sxx immediately followed by an episode digit or 'e' (an
// SxxExx episode token) or by a further digit (a longer number) is skipped.
func seasonTokenIndex(s string) []int {
	for _, loc := range seasonTokenRe.FindAllStringSubmatchIndex(s, -1) {
		if loc[3] < len(s) {
			switch c := s[loc[3]]; {
			case c == 'e' || c == 'E' || (c >= '0' && c <= '9'):
				continue // an episode token or a longer number — not a season marker
			}
		}
		return loc
	}
	return nil
}

// cutTrailingGroupTag removes a trailing single-word release-group tag after
// a separator ("- FanGroup") when the word clears the group-tag shape
// rule; a multi-word segment is preserved whole.
func cutTrailingGroupTag(name string) string {
	m := trailingGroupTagRe.FindStringSubmatchIndex(name)
	if m == nil || !isGroupTagShape(name[m[2]:m[3]]) {
		return name
	}
	return name[:m[0]]
}

// cleanSeriesTitle normalizes separators (".", "_", surrounding "-") to
// spaces, collapses whitespace, and trims. It preserves non-ASCII
// (Cyrillic, etc.).
func cleanSeriesTitle(s string) string {
	s = strings.NewReplacer(".", " ", "_", " ").Replace(s)
	s = strings.TrimSpace(s)
	s = strings.Trim(s, "- ")
	fields := strings.Fields(s)
	return strings.Join(fields, " ")
}

// seriesAtoi parses a decimal integer, returning 0 on any failure (digits come
// from regexp captures, so failure here is unexpected — 0 is a safe fallback).
func seriesAtoi(s string) int {
	n, _ := strconv.Atoi(s)
	return n
}
